दानक्रियाश्च विविधा: क्रियन्ते मोक्षकाङ्‌‍क्षिभि: ॥ २५ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4412,\"bb\":3873,\"url_path\":\"/en/library/bg/17/25/b3873/\",\"body_value\":\"tad ity anabhisandhāya
phalaṁ yajña-tapaḥ-kriyāḥ
dāna-kriyāś ca vividhāḥ
kriyante mokṣa-kāṅkṣibhiḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4413,\"bb\":3874,\"url_path\":\"/en/library/bg/17/25/b3874/\",\"shadow_value\":\"tat – that; iti – thus; anabhisandhāya – without desiring; phalam – the fruitive result; yajña – of sacrifice; tapaḥ – and penance; kriyāḥ – activities; dāna – of charity; kriyāḥ – activities; ca – also; vividhāḥ – various; kriyante – are done; mokṣa-kāṅkṣibhiḥ – by those who actually desire liberation.\",\"word_for_word_value\":[{\"word\":\"tat\",\"translation\":\"that\"},{\"word\":\"iti\",\"translation\":\"thus\"},{\"word\":\"anabhisandhāya\",\"translation\":\"without desiring\"},{\"word\":\"phalam\",\"translation\":\"the fruitive result\"},{\"word\":\"yajña\",\"translation\":\"of sacrifice\"},{\"word\":\"tapaḥ\",\"translation\":\"and penance\"},{\"word\":\"kriyāḥ\",\"translation\":\"activities\"},{\"word\":\"dāna\",\"translation\":\"of charity\"},{\"word\":\"kriyāḥ\",\"translation\":\"activities\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"vividhāḥ\",\"translation\":\"various\"},{\"word\":\"kriyante\",\"translation\":\"are done\"},{\"word\":\"mokṣa-kāṅkṣibhiḥ\",\"translation\":\"by those who actually desire liberation\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4414,\"bb\":3875,\"url_path\":\"/en/library/bg/17/25/b3875/\",\"body_value\":\"Without desiring fruitive results, one should perform various kinds of sacrifice, penance and charity with the word tat. The purpose of such transcendental activities is to get free from material entanglement.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4415,\"bb\":3876,\"url_path\":\"/en/library/bg/17/25/b3876/\",\"body_value\":\"To be elevated to the spiritual position, one should not act for any material gain. Acts should be performed for the ultimate gain of being transferred to the spiritual kingdom, back to home, back to Godhead.\"}]}],\"short_title\":\"Bg. 17.25\",\"medium_title\":\"Bhagavad-gītā As It Is 17.25\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"className\":\"text-vb-link\",\"children\":\"Bhagavad-gītā As It Is\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/17/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/17/\",\"className\":\"text